DROP TABLE IF EXISTS prediction;
DROP TABLE IF EXISTS delta_indicateur;
DROP TABLE IF EXISTS election;
DROP TABLE IF EXISTS indicateur_socio_eco;
DROP TABLE IF EXISTS commune;

CREATE TABLE commune (
    codgeo VARCHAR(5) PRIMARY KEY,
    code_departement CHAR(2) NOT NULL,
    nom_departement VARCHAR(60) NOT NULL,
    region VARCHAR(50) NOT NULL DEFAULT 'Nouvelle-Aquitaine'
);

CREATE TABLE delta_indicateur (
    id INT AUTO_INCREMENT PRIMARY KEY,
    codgeo VARCHAR(5) NOT NULL REFERENCES commune(codgeo),
    delta_P16_POP FLOAT DEFAULT 0,
    delta_P22_POP1564 FLOAT DEFAULT 0,
    delta_P22_ACT1564 FLOAT DEFAULT 0,
    delta_P22_LOG FLOAT DEFAULT 0,
    delta_P22_LOGVAC FLOAT DEFAULT 0,
    delta_revenus_median FLOAT DEFAULT 0,
    delta_P22_EMPLT FLOAT DEFAULT 0,
    delta_taux_chomage FLOAT DEFAULT 0,
    delta_delinquance FLOAT DEFAULT 0,
    delta_diplome_superieur FLOAT DEFAULT 0,
    score_eco_composite FLOAT DEFAULT 0,
    etat_economique ENUM('Boom','Croissance','Stable','Déclin','Crise') NOT NULL
);

CREATE TABLE prediction (
    id INT AUTO_INCREMENT PRIMARY KEY,
    codgeo VARCHAR(5) NOT NULL REFERENCES commune(codgeo),
    annee_reference INT NOT NULL,
    target_ml VARCHAR(20) NOT NULL,
    proba_macron FLOAT NOT NULL,
    proba_lepen FLOAT NOT NULL,
    vainqueur_predit VARCHAR(30) NOT NULL
);

